var PREFIX = "manage_core_feature_records__";
var featureKey = (system, featureId) => `${PREFIX}${system}__${featureId}`;
function readFeatureRecords(system, featureId) {
	try {
		const value = localStorage.getItem(featureKey(system, featureId));
		return value ? JSON.parse(value) : [];
	} catch {
		return [];
	}
}
function writeFeatureRecords(system, featureId, records) {
	try {
		localStorage.setItem(featureKey(system, featureId), JSON.stringify(records));
	} catch {}
}
function downloadTextFile(filename, content, type = "text/plain;charset=utf-8") {
	const blob = new Blob([content], { type });
	const url = URL.createObjectURL(blob);
	const link = document.createElement("a");
	link.href = url;
	link.download = filename;
	document.body.appendChild(link);
	link.click();
	link.remove();
	URL.revokeObjectURL(url);
}
