//#region src/utils/arCustomers.js
var mapARCustomer = (c = {}) => {
	const health = Number(c.health_score ?? 100);
	return {
		id: c.id,
		code: c.code || `CUST-${String(c.id).padStart(3, "0")}`,
		name: c.name || c.company_name || "Unknown Customer",
		type: c.type || "Customer",
		phone: c.phone || "",
		email: c.email || "",
		city: c.city || c.country || "",
		status: c.status || "Active",
		creditLimit: Number(c.credit_limit ?? c.limit ?? 0) || 0,
		outstanding: Number(c.balance ?? 0) || 0,
		group: c.industry || "General",
		rating: Math.round(health / 20),
		currency: c.currency || "USD",
		terms: c.payment_terms || c.terms || "Net 30",
		salesperson: c.salesperson || null,
		taxProfile: c.tax_profile || "Standard",
		priceList: c.price_list || "",
		warehouse: c.warehouse || "Main Warehouse",
		discount: Number(c.discount ?? 0) || 0,
		ntn: c.ntn || "",
		strn: c.strn || "",
		billingAddress: c.address || c.billing_address || "",
		shippingAddress: c.shipping_address || c.address || "",
		riskLevel: health >= 80 ? "Low" : health >= 50 ? "Medium" : "High",
		lastPaymentDate: c.last_payment_date || "-",
		lastInvoiceDate: c.last_invoice_date || "-",
		totalSales: Number(c.total_revenue ?? 0) || 0,
		avgPaymentDays: Number(c.avg_payment_days ?? 0) || 0,
		customerSince: c.since || (c.created_at ? String(c.created_at).slice(0, 10) : "-")
	};
};
var fetchSalesCustomers = async () => {
	try {
		const data = await listARCustomers({ perPage: 1e3 });
		return (Array.isArray(data?.data) ? data.data : []).map(mapARCustomer);
	} catch {
		return [];
	}
};
//#endregion
//#region src/utils/inventoryProducts.js
var mapInventoryProduct = (p = {}) => {
	const stock = Number(p.current_stock ?? p.initial_stock ?? 0) || 0;
	return {
		id: p.id,
		code: p.product_code || p.code || p.sku || "",
		sku: p.sku || p.product_code || "",
		name: p.name || "Unnamed Product",
		category: p.category?.name || p.category_name || p.category || "Uncategorized",
		uom: p.uom || "Units",
		qty: stock,
		rate: Number(p.sales_price ?? p.price ?? p.purchase_cost ?? 0) || 0,
		price: Number(p.sales_price ?? p.price ?? p.purchase_cost ?? 0) || 0,
		tax: Number(p.tax ?? 16) || 16,
		discount: Number(p.discount ?? 0) || 0,
		stock,
		status: String(p.status || "active").toLowerCase() === "inactive" ? "Inactive" : "Active"
	};
};
var fetchSalesProducts = async () => {
	try {
		const res = await listProducts({ per_page: 1e3 });
		return (Array.isArray(res.data?.data) ? res.data.data : Array.isArray(res.data) ? res.data : []).map(mapInventoryProduct);
	} catch {
		return [];
	}
};
